    create table dslistapp.tb_belonging (
        position integer,
        game_id bigint not null,
        list_id bigint not null,
        primary key (game_id, list_id)
    );

    create table dslistapp.tb_game (
        game_year integer,
        score float(53),
        created_at timestamp(6),
        id bigint generated by default as identity,
        genre varchar(255),
        img_url varchar(255),
        long_description TEXT,
        platforms varchar(255),
        short_description TEXT,
        title VARCHAR,
        primary key (id)
    );

    create table dslistapp.tb_game_list (
        created_at timestamp(6),
        id bigint generated by default as identity,
        name varchar(255),
        primary key (id)
    );

    create table dslistapp.tb_users (
        salario numeric(38,2),
        created_at timestamp(6),
        id bigint generated by default as identity,
        email varchar(255),
        nome varchar(255),
        password varchar(255),
        primary key (id)
    );

    create table picpay.transaction (
        amount numeric(38,2),
        created_at timestamp(6),
        id bigint generated by default as identity,
        receiver_id bigint,
        sender_id bigint,
        primary key (id)
    );

    create table picpay.user (
        balance numeric(38,2),
        created_at timestamp(6),
        id bigint generated by default as identity,
        document varchar(255) unique,
        email varchar(255) unique,
        first_name varchar(255),
        last_name varchar(255),
        password varchar(255),
        user_type varchar(255) check (user_type in ('COMMON','MERCHANT')),
        primary key (id)
    );

    alter table if exists dslistapp.tb_belonging 
       add constraint FKrchwdikeu66uky1hf75ym1kh 
       foreign key (list_id) 
       references dslistapp.tb_game_list;

    alter table if exists dslistapp.tb_belonging 
       add constraint FK2slybclee7wdfxhfltbvqkgpg 
       foreign key (game_id) 
       references dslistapp.tb_game;

    alter table if exists picpay.transaction 
       add constraint FKey21a233t8tlwfsbs228q3b2u 
       foreign key (receiver_id) 
       references picpay.user;

    alter table if exists picpay.transaction 
       add constraint FKjpter5yuohdb58gyg6k5nympt 
       foreign key (sender_id) 
       references picpay.user;
